  @override
  String get synthetic_cannabinoidsWithdrawalReference =>
      'انسحاب شبائه القنب الاصطناعية\n\nالمصدر: Craft وآخرون (2022)، Psychopharmacology، PMC\n\nشملت الدراسة 284 شخصًا استخدموا ناهضات مستقبلات القنب الاصطناعية أكثر من عشر مرات في العام السابق وحاولوا التوقف. بعد أكثر من يوم بلا استخدام، أبلغ 82.7٪ عن عرض انسحاب واحد على الأقل. كانت مشكلات النوم (59.2٪) والتهيج (55.6٪) وانخفاض المزاج (54.2٪) الأكثر شيوعًا، كما أُبلغ عن التعرق والخفقان والرغبة في التعاطي والهياج والرعشة. ارتبط الاستخدام الأكثر تكرارًا والأكبر بظهور أعراض أكثر. وعند المقارنة المباشرة، عُدّ انسحاب شبائه القنب الاصطناعية أشد من انسحاب القنب عالي الفعالية.';

  @override
  String get synthetic_cannabinoidsRiskReference =>
      'انسحاب شبائه القنب الاصطناعية والمخاطر الحادة\n\nالمصدر: Cooper (2016)، Current Psychiatry Reports، PMC\n\nتصف التقارير السريرية انسحابًا بعد الاستخدام اليومي قد يبدأ سريعًا بعد الجرعة الأخيرة، مع قلق شديد وأرق وغثيان وقيء وتعرق وخفقان ورعشة وهياج ورغبة في التعاطي. وشملت الحالات الشديدة نوبات اختلاج متكررة ومشكلات قلبية وعائية أو تنفسية. كما تصف المراجعة التسمم بأنه غير متوقع وقد يكون شديدًا، بما في ذلك الذهان ونوبات الاختلاج والحوادث القلبية وإصابة الكلى. الأعراض الشديدة أو المتفاقمة تحتاج إلى تقييم طبي سريع.';

