      'تتعافى كليتيك من تأثيرات الكحول المدرة للبول. الكحول يثبط الهرمون المضاد لإدرار البول، مما يؤدي إلى زيادة التبول والجفاف. بحلول اليوم الثالث، يتحسن توازن السوائل في الجسم بشكل ملحوظ.';

  @override
  String get alcoholMilestone7Title => 'يقوي جهاز المناعة';

  @override
  String get alcoholMilestone7Description =>
      'تستعيد خلايا الدم البيضاء وظيفتها. حتى نوبة واحدة من الإفراط في شرب الخمر يمكن أن تضعف وظيفة المناعة لمدة تصل إلى 24 ساعة، كما أن الشرب المزمن يضعف بشكل كبير قدرة الجسم على مكافحة العدوى.';

  @override
  String get alcoholMilestone14Title => 'يبدأ تعافي حجم الدماغ';

  @override
  String get alcoholMilestone14Description =>
      'يبدأ حجم الدماغ بالتعافي خلال الأسبوعين الأولين. يستمر التفكير والذاكرة في التحسن خلال الأشهر التالية.';

  @override
  String get alcoholMilestone30Title => 'ضغط الدم طبيعي';

  @override
  String get alcoholMilestone30Description =>
      'يُظهر نظام القلب والأوعية الدموية لديك تحسنًا ملحوظًا. يؤدي تناول الكحول بانتظام إلى رفع ضغط الدم، لكن الامتناع عن تناوله لمدة شهر تقريبًا يمكن أن يساعد في إعادة ضغط الدم إلى مستويات صحية.';

  @override
  String get alcoholMilestone60Title => 'تتحسن وظائف الكبد';

  @override
  String get alcoholMilestone60Description =>
      'يُظهر الكبد تحسنًا ملحوظًا في وظائفه. يمكن لهذا العضو المتجدد أن يتعافى بشكل ملحوظ من الأضرار الناجمة عن الكحول، حيث تظهر إنزيمات الكبد وتراكم الدهون تحسنًا خلال شهرين من الامتناع عن ممارسة الجنس.';

  @override
  String get alcoholMilestone90Title => 'تحسن التفكير والذاكرة بشكل كبير';

  @override
  String get alcoholMilestone90Description =>
      'تحقق الأشهر الثلاثة الأولى مكاسب كبيرة في الذاكرة والتركيز وصنع القرار، مع استمرار التعافي خلال الأشهر التالية.';

  @override
  String get alcoholMilestone180Title => 'يستمر حجم الدماغ ووظيفته في التعافي';

  @override
  String get alcoholMilestone180Description =>
      'ستة أشهر من الرصين تمنح الدماغ وقتًا مستدامًا للتعافي. يستمر حجم الدماغ ومهارات التفكير في التحسن.';

  @override
  String get alcoholMilestone365Title => 'قد يبدأ الحد من مخاطر السرطان';

  @override
  String get alcoholMilestone365Description =>
      'سنة واحدة من الامتناع عن ممارسة الجنس قد تبدأ في تقليل خطر الإصابة بالسرطان. في حين أن الكحول يزيد بشكل واضح من خطر الإصابة بالعديد من أنواع السرطان (الكبد والثدي والقولون والمستقيم والمريء)، إلا أن الأبحاث حول الجدول الزمني للحد من المخاطر لا تزال في طور الظهور وتختلف حسب نوع السرطان.';

  @override
  String get smokingMilestone1Title => 'يخلص من أول أكسيد الكربون';

  @override
  String get smokingMilestone1Description =>
      'دمك يتنفس من جديد! وفي غضون 24 ساعة، تنخفض مستويات أول أكسيد الكربون إلى وضعها الطبيعي وترتفع مستويات الأكسجين. لن يحتاج قلبك إلى العمل الإضافي بعد الآن لضخ الدم المسموم إلى جميع أنحاء جسمك.';

  @override
  String get smokingMilestone3Title => 'قمم انسحاب النيكوتين';

  @override
  String get smokingMilestone3Description =>
      'وحش النيكوتين في أشد حالاته غضبًا، لكنك تفوز بالمعركة! لقد ترك كل النيكوتين نظامك. أسوأ الرغبات تحدث الآن، لكنها أيضًا تذكرتك إلى الحرية على الجانب الآخر.';

  @override
  String get smokingMilestone7Title => 'تحسن التذوق والشم بشكل كبير';

  @override
  String get smokingMilestone7Description =>
      'الغذاء على وشك أن يصبح مغامرة مرة أخرى! التدخين يدمر براعم التذوق ومستقبلات الشم. بعد أسبوع واحد، ستعيد اكتشاف النكهات التي نسيت وجودها. الاستعداد لبعض التقدير الغذائي الجاد!';

  @override
  String get smokingMilestone14Title => 'تحسين الدورة الدموية والمشي';

  @override
  String get smokingMilestone14Description =>
      'ساقيك تشكرك في كل خطوة! تتحسن الدورة الدموية بشكل كبير، مما يجعل المشي وممارسة الرياضة أسهل بشكل ملحوظ. تلك السلالم لم تعد مخيفة بعد الآن، أليس كذلك؟';

  @override
  String get smokingMilestone30Title => 'تزيد وظائف الرئة';

  @override
  String get smokingMilestone30Description =>
      'رئتيك تقيمان حفلة عودة! لقد نمت الأهداب من جديد وهي تزيل سنوات من القطران والحطام. تزداد سعة الرئة بشكل كبير، وأصبح سعال المدخن أمرًا تاريخيًا.';

  @override
  String get smokingMilestone90Title =>
      'ينخفض ​​خطر الإصابة بالنوبات القلبية بشكل ملحوظ';

  @override
  String get smokingMilestone90Description =>
      'قلبك يرسل رسائل حب! ثلاثة أشهر خالية من التدخين، وقد انخفض بالفعل خطر الإصابة بأمراض القلب والأوعية الدموية بشكل كبير. يتعافى نظام القلب والأوعية الدموية لديك بشكل أسرع مما تظن أنه ممكن.';

  @override
  String get smokingMilestone180Title => 'يقوي جهاز المناعة';

  @override
  String get smokingMilestone180Description =>
      'لقد حصل جهازك المناعي للتو على ترقية للأبطال الخارقين! ستة أشهر بدون تدخين، وستعود خلايا الدم البيضاء إلى قوتها الكاملة، وتحارب العدوى مثل الأبطال الذين ولدوا ليكونوا.';

  @override
  String get smokingMilestone365Title =>
      'يقلل خطر الإصابة بالسكتة الدماغية بشكل كبير';

  @override
  String get smokingMilestone365Description =>
      'سنة كاملة من الحرية! لقد انخفض خطر الإصابة بالسكتة الدماغية بشكل كبير، وتتعافى الأوعية الدموية بشكل جميل. لقد منحت عقلك رسميًا هدية الدورة الدموية والحماية بشكل أفضل.';

  @override
  String get smokingMilestone1825Title =>
      'تنخفض مخاطر بعض السرطانات بقوة (5–10 سنوات)';

  @override
  String get smokingMilestone1825Description =>
      'خمس سنوات من الانتصار! أنت تدخل الآن نافذة 5–10 سنوات التي ينخفض خلالها الخطر الإضافي لسرطانات الفم والحلق والحنجرة إلى النصف، بينما يستمر خطر السكتة الدماغية في الانخفاض. فوائد المدى الطويل بدأت تعمل بقوة.';

  @override
  String get marijuanaMilestone1Title => 'تبدأ أعراض الانسحاب';

  @override
  String get marijuanaMilestone1Description =>
      'عقلك يتكيف مع الحياة بدون رباعي هيدروكانابينول (THC)! وفي غضون 24 إلى 48 ساعة، قد تشعر بالتهيج أو القلق أو صعوبات في النوم. هذا أمر طبيعي تمامًا، حيث بدأت مستقبلات القنب في إعادة ضبط نفسها.';

  @override
  String get marijuanaMilestone3Title => 'ذروة الأعراض الجسدية';

  @override
  String get marijuanaMilestone3Description =>
      'أنت في أصعب نقطة، ولكن كل شيء شاق من هنا! عادةً ما تشهد الأيام من 2 إلى 6 ذروة أعراض الانسحاب بما في ذلك الصداع والتعرق وتغيرات المزاج. جسمك يعمل بجد لإعادة توازن نفسه.';

  @override
  String get marijuanaMilestone7Title => 'تحسين أنماط النوم';

  @override
  String get marijuanaMilestone7Description =>
      'الأحلام الجميلة تعود! بعد أسبوع بدون تعاطي القنب، تبدأ بنية نومك الطبيعية في العودة إلى طبيعتها. ينتعش نوم حركة العين السريعة، مما يؤدي إلى أحلام أكثر حيوية وتحسين نوعية الراحة.';

  @override
  String get marijuanaMilestone14Title => 'ينتهي الانسحاب الحاد';

  @override
  String get marijuanaMilestone14Description =>
      'لقد مرت العاصفة! معظم أعراض الانسحاب الجسدي تنخفض بشكل ملحوظ بعد أسبوعين. يستقر مزاجك ويصبح العمل اليومي أسهل بكثير. الجزء الأصعب هو خلفك.';

  @override
  String get marijuanaMilestone30Title => 'تتحسن وظيفة الذاكرة';

  @override
  String get marijuanaMilestone30Description =>
      'ضباب عقلك يتلاشى! تظهر الأبحاث أن التعلم اللفظي والذاكرة يبدأان في التحسن بشكل ملحوظ بعد التوقف عن تعاطي القنب. ويبدأ الحُصين، وهو الحُصين، وهو أمر بالغ الأهمية لتكوين الذاكرة، في العمل بشكل أفضل.';

  @override
  String get marijuanaMilestone60Title => 'التركيز يشحذ';

  @override
  String get marijuanaMilestone60Description =>
      'وضع التركيز: مفعل! شهرين بدون الحشيش وقدرتك على التركيز والحفاظ على الاهتمام تظهر تحسنا ملحوظا. تصبح إدارة مهام العمل والدراسة أسهل بشكل ملحوظ.';

  @override
  String get marijuanaMilestone90Title => 'عودة استقرار المزاج';

  @override
  String get marijuanaMilestone90Description =>
      'ثلاثة أشهر بدون الحشيش تجلب مزاجًا أكثر ثباتًا وقلقًا أقل وتحكمًا أفضل في التوتر. حالتك العاطفية تستقر في وضع طبيعي أكثر صحة.';

  @override
  String get marijuanaMilestone180Title => 'استعادة التخطيط وصنع القرار';

  @override
  String get marijuanaMilestone180Description =>
      'لقد عاد مديرك العقلي إلى المسؤولية! ستة أشهر بدون الحشيش تحقق مكاسب كبيرة في التخطيط وصنع القرار وحل المشكلات.';

  @override
  String get marijuanaMilestone365Title => 'استعادة بنية الدماغ';

  @override
  String get marijuanaMilestone365Description =>
      'سنة واحدة بدون الحشيش تمنح مناطق الدماغ المرتبطة بالذاكرة وقتًا طويلاً للتعافي. أصبحت تحسينات التعلم والذاكرة الآن جزءًا من طبيعتك الجديدة.';

  @override
  String get opioidMilestone1Title => 'يبدأ الانسحاب الحاد';

  @override
  String get opioidMilestone1Description =>
      'الجزء الأصعب يبدأ الآن، لكنك لست وحدك. تبلغ أعراض الانسحاب الحادة ذروتها في أول 24 إلى 72 ساعة. هذا هو جسدك الذي يبدأ عملية الشفاء. الدعم الطبي المتخصص أمر بالغ الأهمية خلال هذه المرحلة.';

  @override
  String get opioidMilestone7Title =>
      'الأعراض الجسدية تصل إلى ذروتها وتبدأ في الانخفاض';

  @override
  String get opioidMilestone7Description =>
      'لقد نجحت في اجتياز العاصفة! عادةً ما تبلغ أسوأ أعراض الانسحاب الجسدي ذروتها في الأيام 3-5 تقريبًا وتبدأ في الانخفاض بحلول اليوم السابع. يعمل جسمك بجد لاستعادة توازنه الطبيعي.';

  @override
  String get opioidMilestone14Title => 'أنماط النوم تبدأ في التحسن';

  @override
  String get opioidMilestone14Description =>
      'الأحلام الجميلة تعود! بعد أسبوعين، تبدأ بنية نومك الطبيعية في التعافي. تعطل المواد الأفيونية نوم حركة العين السريعة، لكن دماغك يتعلم الحلم بشكل طبيعي مرة أخرى.';

  @override
  String get opioidMilestone30Title => 'يبدأ التفكير والذاكرة في التعافي';

  @override
  String get opioidMilestone30Description =>
      'ضباب الدماغ يرفع! بعد مرور شهر واحد، تتحسن الذاكرة وصنع القرار والتفكير الواضح مع تعافي الجزء الأمامي من الدماغ من التغيرات المرتبطة بالمواد الأفيونية.';

  @override
  String get opioidMilestone60Title => 'يتحسن التنظيم العاطفي';

  @override
  String get opioidMilestone60Description =>
      'تجد عواطفك إيقاعها الطبيعي مرة أخرى. بعد مرور شهرين على التعافي، يبدأ نظام المكافأة في دماغك في الاستجابة للمتع اليومية. إن الأفعوانية العاطفية تستقر.';

  @override
  String get opioidMilestone90Title => 'تتعافى وظيفة الدوبامين بشكل ملحوظ';

  @override
  String get opioidMilestone90Description =>
      'يقوم نظام المكافأة في دماغك بإقامة حفل ترحيب بعودتك! ثلاثة أشهر نظيفة وتحسنت وظيفة الدوبامين بشكل ملحوظ. تبدأ الأنشطة الطبيعية بالشعور بالمكافأة مرة أخرى - الطعام والموسيقى والعلاقات.';

  @override
  String get opioidMilestone180Title => 'يقوي جهاز المناعة';

  @override
  String get opioidMilestone180Description =>
      'لقد عاد جهازك المناعي للقيام بمهمة الدورية! ستة أشهر من التعافي وتعززت دفاعات الجسم الطبيعية بشكل ملحوظ. أنت مجهز بشكل أفضل لمحاربة العدوى والأمراض.';

  @override
  String get opioidMilestone365Title => 'تحسين اللدونة العصبية وبنية الدماغ';

  @override
  String get opioidMilestone365Description =>
      'لقد كان عقلك مشغولاً بالتجديد! يُظهر عام كامل من التعافي تحسنًا كبيرًا في بنية الدماغ واللدونة العصبية. إن التغييرات الناجمة عن استخدام المواد الأفيونية المزمنة تشفى بشكل جميل.';

  @override
  String get opioidMilestone730Title =>
      'استقرار التعافي على المدى الطويل (سنتان)';

  @override
  String get opioidMilestone730Description =>
      'عامين من القوة والصمود! لقد قمت ببناء مسارات عصبية جديدة، واستراتيجيات التكيف، وأنماط الحياة. تظهر الأبحاث أن الوصول إلى هذا الإنجاز يقلل بشكل كبير من خطر الانتكاس. أنت محارب التعافي!';

  @override
  String get socialMediaMilestone1Title =>
      'التخلص من السموم الرقمية في اليوم الأول! 🎯';

  @override
  String get socialMediaMilestone1Description =>
      'لقد بدأت رسميًا في تجديد دماغك! تظهر الأبحاث أن مجرد التفكير في التحقق من وسائل التواصل الاجتماعي يثير نفس المسارات العصبية التي يسببها الإدمان. لكنك تكسر الدائرة بالفعل - انطلق!';

  @override
  String get socialMediaMilestone3Title => 'FOMO؟ أشبه FO-NO! 😉';

  @override
  String get socialMediaMilestone3Description =>
      'ثلاثة أيام وهؤلاء القلقون \"ما الذي أفتقده؟\" الأفكار تتلاشى بالفعل. أنت تدرب عقلك على أن الحياة الحقيقية هي أكثر إثارة للاهتمام من الخلاصات المنسقة!';

  @override
  String get socialMediaMilestone7Title =>
      'مدى الانتباه: السمكة الذهبية → الإنسان 🧠';

  @override
  String get socialMediaMilestone7Description =>
      'الأسبوع الأول كامل! إن قدرتك على التركيز دون التحقق من هاتفك كل بضع دقائق تتحسن بالفعل. تظهر الدراسات أن أدمغتنا تتوق إلى الحصول على الدوبامين من الإشعارات - لكنك تعلم عقلك كيفية العثور على المكافآت في مكان آخر!';

  @override
  String get socialMediaMilestone14Title => 'النوم مثل الطفل (وليس زومبي) 😴';

  @override
  String get socialMediaMilestone14Description =>
      'أسبوعين دون التمرير قبل النوم = جودة نوم أفضل! الضوء الأزرق المنبعث من الشاشات يمنع إنتاج الميلاتونين، لكن إيقاعات نومك الطبيعية تعود بشكل جميل.';

  @override
  String get socialMediaMilestone30Title =>
      'الأصدقاء الحقيقيون> اللايكات المزيفة 💝';

  @override
  String get socialMediaMilestone30Description =>
      'شهر واحد دون الاتصال بالإنترنت = انخفاض كبير في الشعور بالوحدة والاكتئاب! تثبت الأبحاث أن الحد من وسائل التواصل الاجتماعي يؤدي إلى تحسينات كبيرة في الصحة العقلية. لقد ذهبت إلى أبعد من ذلك!';

  @override
  String get socialMediaMilestone60Title => 'فخ المقارنة: هرب! ✨';

  @override
  String get socialMediaMilestone60Description =>
      'شهرين دون مقارنة اجتماعية مستمرة = ثقة تتخطى الحدود! تظهر الأبحاث باستمرار أن استخدام وسائل التواصل الاجتماعي يرتبط بانخفاض احترام الذات، خاصة من خلال المقارنات الاجتماعية التصاعدية. لقد تحررت من فخ المقارنة!';

  @override
  String get socialMediaMilestone90Title => 'مستوى جامع الهوايات: خبير 🎨';

  @override
  String get socialMediaMilestone90Description =>
      'ثلاثة أشهر = حوالي 270+ ساعة مستصلحة! وهذا وقت كافٍ لتعلم مهارة ما، أو قراءة أكثر من 15 كتابًا، أو التعمق في إحدى الهوايات. يعمل دماغك على تقوية العادات التي تكررها، لذلك تصبح تلك الإجراءات الروتينية خارج الإنترنت أسهل وأكثر تلقائية.';

  @override
  String get socialMediaMilestone180Title => 'اكتمال توهج الصحة العقلية 🌟';

  @override
  String get socialMediaMilestone180Description =>
      'ستة أشهر دون اتصال بالإنترنت وأنت مزدهر رسميًا! تظهر الدراسات طويلة المدى أن تقليل استخدام وسائل التواصل الاجتماعي يؤدي إلى تحسينات مستدامة في الرفاهية واحترام الذات والرضا عن الحياة. أنت دليل حي على أن الحياة أفضل في العالم الحقيقي!';

  @override
  String get socialMediaMilestone365Title =>
      'تم تحقيق برنامج Zen Master الرقمي 🏆';

  @override
  String get socialMediaMilestone365Description =>
      'سنة كاملة من العيش المتعمد! لقد استعدت أكثر من 1000 ساعة، وكوّنت علاقات أعمق، وأثبتت أن أفضل اللحظات في الحياة ليست مخصصة للمشاركة، بل للتجربة. أنت رسميًا أسطورة العافية الرقمية!';

  @override
  String get nicotinePouchesMilestone1Title => 'التذوق والشم يبدأان في التعافي';

  @override
  String get nicotinePouchesMilestone1Description =>
      'النيكوتين يضعف براعم التذوق ومستقبلات الشم لديك. بعد 24 ساعة فقط من عدم وجود أكياس، تبدأ هذه الحواس جولة عودتها! الطعام على وشك أن يكون مذاقه رائعًا مرة أخرى.';

  @override
  String get nicotinePouchesMilestone3Title => 'تم مسح النيكوتين بالكامل';

  @override
  String get nicotinePouchesMilestone3Description =>
