  @override
  String get tcaMilestone3Title => 'اليوم 3: ارتداد كوليني';

  @override
  String get tcaMilestone3Description =>
      'يمكن أن يسبب إيقاف مضادات الاكتئاب ثلاثية الحلقات أعراض انسحاب حقيقية، ويُعد فرط النشاط الكوليني إحدى الآليات المقترحة. قد تظهر مبكرًا أعراض مثل الغثيان والإسهال وألم البطن والأرق والقلق والهياج والصداع، خاصة بعد الإيقاف المفاجئ أو الخفض السريع. اليوم الثالث إنجاز؛ توقيت الأعراض وشدتها يختلفان من شخص لآخر.';

  @override
  String get tcaMilestone7Title => 'أسبوع واحد: اجتزت المرحلة الأولى';

  @override
  String get tcaMilestone7Description =>
      'يبدأ انسحاب مضادات الاكتئاب عادة خلال بضعة أيام وغالبًا يستمر بضعة أسابيع. بعد أسبوع قد تظل أعراض مثل الغثيان والتعرق واضطراب النوم والخفقان والدوخة موجودة. سبعة أيام تقدم حقيقي، ويمكن أن يستمر التحسن وفق جداول زمنية مختلفة.';

  @override
  String get tcaMilestone14Title =>
      'أسبوعان: الانسحاب الحاد غالبًا يبدأ بالانحسار';

  @override
  String get tcaMilestone14Description =>
      'عادةً ما تستمر أعراض إيقاف مضادات الاكتئاب مثل الغثيان والأرق واضطراب التوازن والأعراض الحسية وفرط الاستثارة من أسبوع إلى أسبوعين. عند اليوم 14 يصل كثير من الناس إلى نهاية هذه المرحلة الحادة.';

  @override
  String get tcaMilestone30Title => 'شهر واحد: الانسحاب الحاد هدأ غالبًا';

  @override
  String get tcaMilestone30Description =>
      'تستمر أعراض التوقف عن مضادات الاكتئاب عادةً من أسبوع إلى أسبوعين. عند 30 يومًا، يكون معظم الناس قد تجاوزوا تلك المرحلة الحادة، وتكون الأعراض الشبيهة بالإنفلونزا والغثيان واضطراب التوازن والأرق والاضطرابات الحسية وفرط الاستثارة قد هدأت أو زالت عادةً.';

  @override
  String get tcaMilestone90Title =>
      'ثلاثة أشهر: الانسحاب الحاد أصبح خلفك غالبًا';

  @override
  String get tcaMilestone90Description =>
      'تستمر أعراض التوقف عن مضادات الاكتئاب عادةً من أسبوع إلى أسبوعين. عند 90 يومًا، تكون قد تجاوزت الحد الأعلى لهذه الفترة الحادة المعتادة بأكثر من عشرة أسابيع؛ وعادةً ما تكون الأعراض الشبيهة بالإنفلونزا والغثيان واضطراب التوازن والأرق والاضطرابات الحسية وفرط الاستثارة قد هدأت أو زالت منذ مدة.';

  @override
  String get tcaMilestone180Title => 'ستة أشهر: الغالبية بلا انتكاسة';

  @override
  String get tcaMilestone180Description =>
      'بين الأشخاص الذين أوقفوا مضادات الاكتئاب بعد علاج الاكتئاب الشديد، وجد تحليل تلوي لـ35 تجربة أن معدل الانتكاس المجمع بعد ستة أشهر بلغ 34.8% — أي أن نحو 65% ظلوا بلا انتكاسة. هذه فترة استقرار هائلة.';

  @override
  String get tcaMilestone365Title => 'سنة واحدة: الغالبية بلا انتكاسة';

  @override
  String get tcaMilestone365Description =>
      'بين الأشخاص الذين أوقفوا مضادات الاكتئاب بعد علاج الاكتئاب الشديد، وجد تحليل تلوي لـ35 تجربة أن معدل الانتكاس المجمع بعد 12 شهرًا بلغ 45.12% — أي أن نحو 55% ظلوا بلا انتكاسة لعام كامل. هذه محطة كبرى من الاستقرار طويل الأمد.';

