  }

  @override
  String get vapingDay1Description =>
      'اليوم الأول بلا فيب. إذا كان الفيب الذي تستخدمه يحتوي على النيكوتين، فقد تكون الرغبة الشديدة أو التهيّج أو التوتر أو المزاج المنخفض أو سوء النوم أو صعوبة التركيز أعراض انسحاب النيكوتين — وليست سببًا لإطعامه نيكوتين جديدًا. في كل الأحوال، أنت تكسر حلقة الفيب بالفعل.';

  @override
  String get vapingDay3Description =>
      'ثلاثة أيام بلا فيب. في دراسة سريرية على مدخنين سابقين كانوا يستخدمون السجائر الإلكترونية يوميًا، زادت أعراض الانسحاب خلال أول يومين من الامتناع ثم اتبعت نمط الصعود والهبوط المعتاد. لقد عبرت الموجة المبكرة الحادة؛ قد تظهر الرغبة مجددًا، لكنها ليست من يمسك بالمقود.';

  @override
  String get vapingDay7Description =>
      'سبعة أيام كاملة من دون استنشاق رذاذ الفيب. أسبوع بلا تعرّض جديد من الفيب للنيكوتين أو الجسيمات فائقة الدقة أو المعادن الثقيلة أو المركبات العضوية المتطايرة أو غيرها من المواد الضارة التي قد يحملها الرذاذ. سلسلة نظيفة — واصل.';

  @override
  String vapingLongStreakDescription(int days) {
    return '$days يومًا من دون أخذ نفخة أخرى من رذاذ الفيب. أي $days يومًا بلا تعرّض جديد من الفيب للمواد الضارة التي قد يحملها الرذاذ. وإذا كان الفيب يحتوي على النيكوتين، فهي أيضًا $days يومًا من دون تعزيز ذلك الاعتماد. سلسلة ضخمة — استمر.';
  }

  @override
  String get vapingWithdrawalReference =>
      'الامتناع عن السجائر الإلكترونية وأعراض الانسحاب\n\nالمصدر: Hughes وزملاؤه، Nicotine & Tobacco Research (2020)\n\nلدى 109 مدخنين سابقين كانوا يستخدمون السجائر الإلكترونية يوميًا، أدت ستة أيام من الامتناع المؤكد بيولوجيًا إلى زيادة أعراض انسحاب النيكوتين والرغبة. اتبعت الأعراض نمط الصعود والهبوط المعتاد للانسحاب، مع زيادة واضحة خلال أول يومين. تؤكد الدراسة أن انسحاب السجائر الإلكترونية حقيقي، لكنها لا تحدد جدول تعافٍ يوميًا موحدًا للجميع.';

  @override
  String get vapingHealthReference =>
      'ما الذي يعرّضك له الفيب\n\nالمصدر: CDC — Health Effects of Vaping\n\nتقول CDC إن معظم السجائر الإلكترونية تحتوي على نيكوتين مسبب للإدمان. وقد يحتوي الرذاذ على النيكوتين ومواد كيميائية مسرطنة ومعادن ثقيلة مثل النيكل والقصدير والرصاص وجسيمات دقيقة تصل عميقًا إلى الرئتين ومركبات عضوية متطايرة وبعض مواد النكهة الضارة. قد يسبب انسحاب النيكوتين التهيّج والقلق أو التوتر والمزاج المنخفض ومشكلات النوم والتركيز والجوع والرغبة، وتخف هذه الأعراض مع الوقت. ما زالت الآثار طويلة المدى للفيب قيد الدراسة، لذلك يحتفل Quitter بالامتناع الحقيقي بدل استعارة جداول السجائر الخاصة بأول أكسيد الكربون والقطران والسرطان أو مخاطر القلب.';
}
